#[inline]
fn parse_definition(p: &mut GraphqlParser) -> ParsedSyntax {
    let keyword = if is_at_string(p) { p.nth(1) } else { p.cur() };
    match keyword {
        T![query] | T![mutation] | T![subscription] => parse_operation_definition(p),
