    if p.diagnostics().is_empty() {
        println!("  OK no diagnostics");
    } else {
        for d in p.diagnostics() {
            let err = d
                .clone()
                .with_file_path("t.graphql")
                .with_file_source_code(src);
            print!("{}", render(&err));
        }
    }
}

