    check("fields only", "extend type A { b: C }");
    check("directive only", "extend type A @d");
    check("implements only", "extend type A implements B");
    check("implements + directive", "extend type A implements B @d");
    check("directive + fields", "extend type A @d { b: C }");
    check("impl+dir+fields", "extend type A implements B @d { b: C }");
    check("EMPTY (err)", "extend type A");
    check("missing brace (err)", "extend type A b: C }");
    check("recovery", "extend type A\ntype B { c: D }");
}
